      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      const sl = line, sc = col
      adv(); adv()
      let depth = 1
      while (depth > 0) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') { adv(); adv(); depth++ }
        else if (cs[i] === '*' && cs[i + 1] === '/') { adv(); adv(); depth-- }
        else adv()
      }
      continue
    }
    const tl = line, tc = col
    const push = (kind, body) => tokens.push({ line: tl, col: tc, kind, body })

    if (c === 'r' && cs[i + 1] === '"') {
      adv(); adv()
      let s = ''
