    if (isIdStart(c)) {
      let s = ''
      while (i < n && isIdPart(cs[i])) s += adv()
      push(KEYWORDS.has(s) ? 'keyword' : 'ident', s)
      continue
    }
    if (isDigit(c)) {
      let s = ''
      const take = () => { s += adv() }
      const run = (isD) => {
        if (!isD(cs[i])) return false
        take()
        while (i < n) {
          if (isD(cs[i])) take()
          else if (cs[i] === '_' && isD(cs[i - 1]) && isD(cs[i + 1])) take()
          else break
        }
        return true
      }
      let ok = true
      const p = cs[i + 1]
      if (c === '0' && (p === 'x' || p === 'X' || p === 'b' || p === 'B' || p === 'o' || p === 'O')) {
        take(); take()
        const f = 'xX'.includes(p) ? isHex : 'bB'.includes(p) ? isBin : isOct
        ok = run(f)
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { take(); run(isDigit) }
        if (cs[i] === 'e' || cs[i] === 'E') {
          const a = cs[i + 1], b = cs[i + 2]
          if (isDigit(a)) { take(); run(isDigit) }
          else if ((a === '+' || a === '-') && isDigit(b)) { take(); take(); run(isDigit) }
        }
      }
      if (!ok || isIdPart(cs[i])) {
        while (i < n && isIdPart(cs[i])) take()
        throw new ScanError(tl, tc, `invalid number ${s}`)
      }
      push('number', s)
      continue
    }
    if (c === '"') {
      adv()
      let s = ''
      while (true) {
        if (i >= n) throw new ScanError(tl, tc, 'unterminated string')
        const el = line, ec = col
        const d = adv()
        if (d === '"') break
        if (d === '\n') throw new ScanError(el, ec, 'newline in string')
        if (d !== '\\') { s += d; continue }
        if (i >= n) throw new ScanError(tl, tc, 'unterminated string')
        const e = adv()
        const bad = () => new ScanError(el, ec, `invalid escape \\${e}`)
