        p.ws()
        if (!p.atEnd()) fail('trailing text after a table header')
        let t = root
        const walked = []
        for (let k = 0; k < keys.length - 1; k++) {
          t = descend(t, walked, keys[k])
          walked.push(keys[k])
        }
        const last = keys[keys.length - 1]
        const full = [...walked, last].join('.')
        const ex = t.map.get(last)
        if (!aot) {
          if (ex === undefined) {
            const nt = new Table(); nt.defined = true
            t.map.set(last, nt); cur = nt
