  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: line ${e.line}: ${e.message}\n`)
  process.exit(2)
}
if (args[0] === 'json') process.stdout.write(toJson(doc, 0) + '\n')
else {
  const out = []
  keyLines(doc, null, out)
  process.stdout.write(out.map((l) => l + '\n').join(''))
