const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'

export class ScanError extends Error {
  constructor(line, col, reason) {
    super(`${line}:${col}: ${reason}`)
  }
}

const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9A-Fa-f]$/.test(c)

export function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0, line = 1, col = 1

  const advance = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const adv = (k) => { for (let j = 0; j < k; j++) advance() }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { advance(); continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') advance()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      const sl = line, sc = col
      adv(2)
      let depth = 1
      while (depth > 0) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (cs[i] === '*' && cs[i + 1] === '/') { adv(2); depth-- }
        else if (cs[i] === '/' && cs[i + 1] === '*') { adv(2); depth++ }
        else advance()
      }
      continue
    }
    const sl = line, sc = col
    const push = (kind, body) => tokens.push({ line: sl, col: sc, kind, body })

    if (c === 'r' && cs[i + 1] === '"') {
      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) throw new ScanError(sl, sc, 'unterminated string')
      const val = cs.slice(i + 2, j).join('')
      adv(j + 1 - i)
      push('rawstring', JSON.stringify(val))
      continue
    }
    if (isIdStart(c)) {
      const s = i
      while (i < n && isIdPart(cs[i])) advance()
      const w = cs.slice(s, i).join('')
      push(KEYWORDS.has(w) ? 'keyword' : 'ident', w)
      continue
    }
    if (isDigit(c)) {
      const s = i
      let ok = true
      const run = (pred) => {
        let cnt = 0
        while (i < n) {
          if (pred(cs[i])) { advance(); cnt++ }
          else if (cs[i] === '_' && cnt > 0 && pred(cs[i + 1])) advance()
          else break
        }
        return cnt
      }
      const p = (cs[i + 1] || '').toLowerCase()
      if (c === '0' && (p === 'x' || p === 'b' || p === 'o')) {
        adv(2)
        const pred = p === 'x' ? isHex : p === 'b' ? (d) => d === '0' || d === '1' : (d) => d !== undefined && d >= '0' && d <= '7'
        if (run(pred) === 0) ok = false
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { advance(); run(isDigit) }
        if (cs[i] === 'e' || cs[i] === 'E') {
          if (isDigit(cs[i + 1])) { advance(); run(isDigit) }
          else if ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2])) { adv(2); run(isDigit) }
        }
      }
      if (!ok || isIdPart(cs[i])) {
        while (i < n && isIdPart(cs[i])) advance()
