      }
      push('number', cs.slice(s, i).join(''))
      continue
    }
    if (c === '"') {
      advance()
      let val = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = cs[i]
        if (d === '\n') throw new ScanError(line, col, 'newline in string')
        if (d === '"') { advance(); break }
        if (d !== '\\') { val += advance(); continue }
        const el = line, ec = col
        advance()
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = cs[i]
        const bad = () => new ScanError(el, ec, `invalid escape \\${e}`)
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '0': '\0' }
        if (e in simple) { advance(); val += simple[e] }
        else if (e === 'x') {
          if (!(isHex(cs[i + 1]) && isHex(cs[i + 2]))) throw bad()
          val += String.fromCharCode(parseInt(cs[i + 1] + cs[i + 2], 16))
          adv(3)
        } else if (e === 'u') {
          if (cs[i + 1] !== '{') throw bad()
          let j = i + 2
          while (isHex(cs[j])) j++
          if (j === i + 2 || cs[j] !== '}') throw bad()
          const v = parseInt(cs.slice(i + 2, j).join(''), 16)
          if (v > 0x10ffff) throw bad()
          val += String.fromCodePoint(v)
          adv(j + 1 - i)
        } else throw bad()
      }
      push('string', JSON.stringify(val))
      continue
    }
    const two = c + (cs[i + 1] || '')
    if (PUNCT2.includes(two)) { adv(2); push('punct', two); continue }
    if (PUNCT1.includes(c)) { advance(); push('punct', c); continue }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}
