function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < x.length && i < y.length; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sortedKeys = (m) => [...m.keys()].sort(cmp)

function js(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (n.t === 'table') {
    const ks = sortedKeys(n.m)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + js(n.m.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((v) => pad + js(v, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(n.v)
}
export const toJson = (root) => js(root, 0) + '\n'

export function toKeys(root) {
  const out = []
  const walk = (n, path) => {
    if (n.t === 'table') {
      for (const k of sortedKeys(n.m)) {
        const p = path === null ? k : path + '.' + k
        const c = n.m.get(k)
        out.push(p + ' ' + c.t)
        walk(c, p)
      }
    } else if (n.t === 'array') {
      n.items.forEach((c, i) => {
        const p = path + '[' + i + ']'
        out.push(p + ' ' + c.t)
        walk(c, p)
      })
    }
  }
  walk(root, null)
  return out.length ? out.join('\n') + '\n' : ''
}
