  const q = rest.indexOf('?')
  if (q >= 0) { r.query = rest.slice(q + 1); rest = rest.slice(0, q) }
  if (rest.startsWith('//')) {
    const e = rest.slice(2).search(/\//)
    if (e >= 0) { r.authority = rest.slice(2, 2 + e); rest = rest.slice(2 + e) }
    else { r.authority = rest.slice(2); rest = '' }
  }
  r.path = rest
  return r
}

function splitAuth(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : undefined
  const hp = a.slice(at + 1)
  const from = hp.lastIndexOf(']')
  const c = hp.indexOf(':', from + 1 > 0 ? from + 1 : 0)
  if (c < 0) return { userinfo, host: hp, port: undefined }
  return { userinfo, host: hp.slice(0, c), port: hp.slice(c + 1) }
