export function check(r) {
  const a = r.authority !== undefined ? splitAuth(r.authority) : {}
  const list = [['path', r.path], ['userinfo', a.userinfo], ['host', a.host], ['query', r.query], ['fragment', r.fragment]]
  for (const [n, v] of list) if (bad(v)) return n
  return null
}

function pct(s) {
  if (s === undefined) return s
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
  })
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

export function removeDots(p) {
  let inp = p, out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
