    else {
      const j = inp.indexOf('/', 1)
      const seg = j < 0 ? inp : inp.slice(0, j)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

const DEFAULTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function serialize(r) {
  let s = ''
  if (r.scheme !== undefined) s += r.scheme + ':'
  if (r.authority !== undefined) s += '//' + r.authority
  s += r.path
  if (r.query !== undefined) s += '?' + r.query
  if (r.fragment !== undefined) s += '#' + r.fragment
  return s
