export function parse(s) {
  const r = { scheme: undefined, authority: undefined, path: '', query: undefined, fragment: undefined }
  let i = 0
  const m = /^([^:/?#]+):/.exec(s)
  if (m) { r.scheme = m[1]; i = m[0].length }
  let rest = s.slice(i)
  const h = rest.indexOf('#')
  if (h >= 0) { r.fragment = rest.slice(h + 1); rest = rest.slice(0, h) }
  const q = rest.indexOf('?')
  if (q >= 0) { r.query = rest.slice(q + 1); rest = rest.slice(0, q) }
  if (rest.startsWith('//')) {
    const e = rest.slice(2).search(/\//)
    if (e >= 0) { r.authority = rest.slice(2, 2 + e); rest = rest.slice(2 + e) }
