export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = [] // Map name -> votes per round
  const rounds = []
  for (let number = 1; ; number++) {
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    let total = 0n
    for (const b of ballots) {
      total += b.count
      const c = b.prefs.find((p) => continuing.has(p))
      if (c) {
        votes.set(c, votes.get(c) + b.count)
        active += b.count
      }
    }
    history.push(votes)
    const lines = [...votes].map(([name, v]) => ({ name, votes: v })).sort((a, b) =>
      a.votes > b.votes ? -1 : a.votes < b.votes ? 1 : a.name < b.name ? -1 : a.name > b.name ? 1 : 0)
    const round = { number, lines, exhausted: total - active, eliminated: null }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    const top = lines[0]
    if (top.votes * 2n > active) return { rounds, winner: top.name }
    let set = lines.filter((l) => l.votes === lines[lines.length - 1].votes).map((l) => l.name)
    for (let r = 0; set.length > 1 && r < history.length; ) {
      const vs = set.map((c) => history[r].get(c))
      const min = vs.reduce((a, b) => (b < a ? b : a))
      if (vs.every((v) => v === min)) { r++; continue }
      set = set.filter((c, k) => vs[k] === min)
      r = 0
    }
    const out = set.reduce((a, b) => (b > a ? b : a))
    round.eliminated = out
    continuing.delete(out)
  }
}
