  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push(keyOf(c, r))
  return out
}

function collectDeps(node, set) {
  switch (node.n) {
    case 'ref': { const p = parseAddr(node.a); if (p) set.add(keyOf(p.col, p.row)); break }
    case 'range': { const l = rangeCells(node); if (l) l.forEach((k) => set.add(k)); break }
    case 'bin': collectDeps(node.l, set); collectDeps(node.r, set); break
    case 'neg': collectDeps(node.x, set); break
    case 'call': node.args.forEach((a) => collectDeps(a, set)); break
  }
}

const parsed = new Map()
function getParsed(cell) {
  if (!parsed.has(cell.key)) parsed.set(cell.key, parseFormula(cell.content.slice(1)))
  return parsed.get(cell.key)
}
const memo = new Map()
const visiting = new Set()

function cellValue(key) {
  if (memo.has(key)) return memo.get(key)
  const cell = cells.get(key)
  if (!cell) return 0
  if (visiting.has(key)) return err('#CYCLE!')
  visiting.add(key)
  let v
  const c = cell.content
  if (c[0] === '=') {
    const tree = getParsed(cell)
    v = tree ? evalNode(tree) : err('#ERR!')
  } else if (c === '') v = 0
  else if (NUM.test(c)) v = Number(c)
  else if (ERRS.has(c)) v = err(c)
  else v = { t: c }
  visiting.delete(key)
  memo.set(key, v)
  return v
}

function toNum(v) {
  if (typeof v === 'number') return v
  if (isBool(v)) return v ? 1 : 0
  return err('#VALUE!')
}
const finite = (x) => (Number.isFinite(x) ? x : err('#DIV/0!'))
const rank = (v) => (typeof v === 'number' ? 0 : isText(v) ? 1 : 2)

function cpCompare(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const m = Math.min(x.length, y.length)
  for (let i = 0; i < m; i++) {
    const p = x[i].codePointAt(0), q = y[i].codePointAt(0)
    if (p !== q) return p < q ? -1 : 1
  }
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}

function evalNode(n) {
  switch (n.n) {
    case 'num': return n.v
    case 'bool': return n.v
    case 'ref': {
      const p = parseAddr(n.a)
      return p ? cellValue(keyOf(p.col, p.row)) : err('#REF!')
    }
    case 'range': return err('#ERR!')
    case 'neg': {
      const v = evalNode(n.x)
      if (isErr(v)) return v
      const x = toNum(v)
      if (isErr(x)) return x
      return n.op === '-' ? (x === 0 ? 0 : -x) : x
    }
    case 'bin': {
      const l = evalNode(n.l)
      if (isErr(l)) return l
      const r = evalNode(n.r)
      if (isErr(r)) return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const rl = rank(l), rr = rank(r)
        let cmp
        if (rl !== rr) cmp = rl < rr ? -1 : 1
        else if (rl === 0) cmp = l < r ? -1 : l > r ? 1 : 0
        else if (rl === 1) cmp = cpCompare(l.t, r.t)
        else cmp = l === r ? 0 : l ? 1 : -1
        switch (n.op) {
          case '=': return cmp === 0
          case '<>': return cmp !== 0
          case '<': return cmp < 0
          case '<=': return cmp <= 0
          case '>': return cmp > 0
          default: return cmp >= 0
        }
      }
      const a = toNum(l)
      if (isErr(a)) return a
      const b = toNum(r)
      if (isErr(b)) return b
      switch (n.op) {
        case '+': return finite(a + b)
        case '-': return finite(a - b)
        case '*': return finite(a * b)
        case '/': return b === 0 ? err('#DIV/0!') : finite(a / b)
        default: return finite(Math.pow(a, b))
      }
    }
    case 'call': return evalCall(n)
  }
}

const FUNCS = { SUM: [1, Infinity], MIN: [1, Infinity], MAX: [1, Infinity], COUNT: [1, Infinity], AVG: [1, Infinity], ABS: [1, 1], IF: [3, 3] }

function evalCall(n) {
  const spec = FUNCS[n.name]
  if (!spec) return err('#NAME?')
  const k = n.args.length
  if (k < spec[0] || k > spec[1]) return err('#ERR!')
  if (n.name === 'IF') {
    if (n.args.some((a) => a.n === 'range')) return err('#ERR!')
    const c = evalNode(n.args[0])
    if (isErr(c)) return c
    if (isText(c)) return err('#VALUE!')
    const truth = isBool(c) ? c : c !== 0
    return evalNode(n.args[truth ? 1 : 2])
  }
  const vals = []
  for (const a of n.args) {
    if (a.n === 'range') {
      const l = rangeCells(a)
      if (!l) vals.push(err('#REF!'))
      else for (const key of l) vals.push(cellValue(key))
    } else vals.push(evalNode(a))
  }
  const firstErr = vals.find(isErr)
  if (firstErr) return firstErr
  if (n.name === 'COUNT') return vals.filter((v) => typeof v === 'number').length
  if (n.name === 'ABS' && vals.length !== 1) return err('#ERR!')
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (isErr(x)) return x
    nums.push(x)
  }
  switch (n.name) {
    case 'SUM': return finite(nums.reduce((s, x) => s + x, 0))
    case 'MIN': return nums.reduce((a, b) => (b < a ? b : a))
    case 'MAX': return nums.reduce((a, b) => (b > a ? b : a))
    case 'AVG': return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
    default: return Math.abs(nums[0])
  }
}

function fmt(v) {
  if (typeof v === 'number') return String(Number(v.toPrecision(10)))
  if (isBool(v)) return v ? 'TRUE' : 'FALSE'
  if (isErr(v)) return v.e
  return v.t
}

let out = ''
if (mode[0] === 'values') {
  for (const c of sorted) out += `${c.key}=${fmt(cellValue(c.key))}\n`
} else {
  for (const c of sorted) {
    const set = new Set()
    if (c.content[0] === '=') {
      const tree = getParsed(c)
      if (tree) collectDeps(tree, set)
    }
    const list = [...set].map((k) => ({ k, ...parseAddr(k) })).sort((a, b) => a.col - b.col || a.row - b.row)
    out += `${c.key}:${list.map((x) => ' ' + x.k).join('')}\n`
  }
}
process.stdout.write(out)
"}

