{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}
const mode = args[0]

class Fail extends Error {}
const fail = (n, m) => { throw new Fail(`error: line ${n}: ${m}`) }
const ident = /^[A-Za-z0-9_.\/:-]+$/
const uint = /^(0|[1-9][0-9]*)$/

function num(n, field, s, least) {
  if (!uint.test(s) || BigInt(s) < BigInt(least)) fail(n, `${field} must be an integer of at least ${least}`)
  return BigInt(s)
}

function run(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const out = []
  const stats = new Map()
  let started = false
  let lastTick = null
  let allowed = 0, denied = 0

  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line[0] === '#') return
    const t = line.split(/\s+/)
    const d = t[0]
    if (d === 'bucket' || d === 'window') {
      const isB = d === 'bucket'
      const want = isB ? 5 : 4
      if (t.length !== want) fail(n, isB ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
      if (started) fail(n, 'declarations must come before the first event')
      if (!ident.test(t[1])) fail(n, `invalid policy name ${t[1]}`)
      let p
      if (isB) {
        const capacity = num(n, 'capacity', t[2], 1)
        const refill = num(n, 'refill', t[3], 0)
        const per = num(n, 'per', t[4], 1)
        p = { kind: 'bucket', name: t[1], capacity, refill, per, states: new Map() }
      } else {
        const limit = num(n, 'limit', t[2], 0)
        const span = num(n, 'span', t[3], 1)
        p = { kind: 'window', name: t[1], limit, span, states: new Map() }
      }
      if (policies.has(t[1])) fail(n, `policy ${t[1]} is declared twice`)
      policies.set(t[1], p)
    } else if (d === 'route') {
      if (t.length < 3) fail(n, 'expected route <prefix> <policy>...')
      if (started) fail(n, 'declarations must come before the first event')
      if (!ident.test(t[1])) fail(n, `invalid route prefix ${t[1]}`)
      if (routes.has(t[1])) fail(n, `prefix ${t[1]} is routed twice`)
      const list = []
      for (const name of t.slice(2)) {
        if (!policies.has(name)) fail(n, `unknown policy ${name}`)
        list.push(policies.get(name))
      }
      routes.set(t[1], list)
    } else if (d === 'event') {
      if (t.length !== 3) fail(n, 'expected event <tick> <key>')
      const tick = num(n, 'tick', t[1], 0)
      const key = t[2]
      if (!ident.test(key)) fail(n, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) fail(n, `tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      started = true
      let best = null
      for (const pre of routes.keys()) {
        if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
      }
      let refused = null
      if (best !== null) {
        const list = routes.get(best)
        const sts = list.map((p) => {
          let s = p.states.get(key)
          if (p.kind === 'bucket') {
            if (!s) { s = { tokens: p.capacity * p.per, last: tick }; p.states.set(key, s) }
            else {
              s.tokens += p.refill * (tick - s.last)
              const cap = p.capacity * p.per
              if (s.tokens > cap) s.tokens = cap
              s.last = tick
            }
          } else {
            if (!s) { s = { ticks: [] }; p.states.set(key, s) }
            s.ticks = s.ticks.filter((x) => x > tick - p.span)
          }
          return s
        })
        for (let j = 0; j < list.length; j++) {
          const p = list[j], s = sts[j]
          const ok = p.kind === 'bucket' ? s.tokens >= p.per : BigInt(s.ticks.length) < p.limit
          if (!ok) { refused = p; break }
        }
        if (!refused) {
          list.forEach((p, j) => {
            if (p.kind === 'bucket') sts[j].tokens -= p.per
            else sts[j].ticks.push(tick)
          })
        }
      }
      let st = stats.get(key)
      if (!st) { st = { a: 0, d: 0 }; stats.set(key, st) }
      if (refused) { st.d++; denied++; out.push(`${t[1]} ${key} deny ${refused.name}`) }
      else { st.a++; allowed++; out.push(`${t[1]} ${key} allow`) }
    } else {
      fail(n, `unknown directive ${d}`)
    }
  })

  if (mode === 'replay') return out.map((l) => l + '\n').join('')
  const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  let s = ''
  for (const k of keys) s += `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}\n`
  return s + `total allowed=${allowed} denied=${denied}\n`
}

try {
  const res = run(readFileSync(0, 'utf8'))
  process.stdout.write(res)
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exit(2)
}
EOF
