const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

const out = []
let conflict = false
const emit = (kind, ...a) => out.push({ kind, a })
let pos = 0
let k = 0
const sides = [mine, theirs]
while (k < all.length) {
  const rs = all[k].bs
  let re = all[k].be
  const group = [all[k++]]
  while (k < all.length && all[k].bs <= re) {
    re = Math.max(re, all[k].be)
    group.push(all[k++])
  }
