export function parse(s) {
  const r = { scheme: undefined, authority: undefined, path: '', query: undefined, fragment: undefined }
  let m = /^([^:/?#]+):/.exec(s)
  if (m) { r.scheme = m[1]; s = s.slice(m[0].length) }
  if (s.startsWith('//')) {
    const end = s.slice(2).search(/[/?#]/)
    const stop = end < 0 ? s.length : end + 2
    r.authority = s.slice(2, stop)
    s = s.slice(stop)
  }
  const h = s.indexOf('#')
  if (h >= 0) { r.fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { r.query = s.slice(q + 1); s = s.slice(0, q) }
  r.path = s
  return r
}

export function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : undefined
  const hp = a.slice(at + 1)
  const from = hp.lastIndexOf(']') + 1
  const c = hp.indexOf(':', from)
  if (c < 0) return { userinfo, host: hp, port: undefined }
  return { userinfo, host: hp.slice(0, c), port: hp.slice(c + 1) }
}

export function removeDots(input) {
  let out = ''
  while (input.length) {
    if (input.startsWith('../')) input = input.slice(3)
    else if (input.startsWith('./')) input = input.slice(2)
    else if (input.startsWith('/./')) input = input.slice(2)
    else if (input === '/.') input = '/'
    else if (input.startsWith('/../') || input === '/..') {
      input = input === '/..' ? '/' : input.slice(3)
      out = out.slice(0, Math.max(out.lastIndexOf('/'), 0))
    } else if (input === '.' || input === '..') input = ''
    else {
      const i = input.indexOf('/', 1)
      const seg = i < 0 ? input : input.slice(0, i)
      out += seg
      input = input.slice(seg.length)
    }
  }
  return out
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/
const pct = (s) => s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
  const c = String.fromCharCode(parseInt(h, 16))
  return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
})
const truncated = (s) => /%(?![0-9A-Fa-f]{2})/.test(s)
const lowerAscii = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const DEFAULT_PORT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export class UriError extends Error {}

export function normalize(r) {
  const scheme = r.scheme === undefined ? undefined : lowerAscii(r.scheme)
  let a
  if (r.authority !== undefined) a = splitAuthority(r.authority)
  const checks = [['path', r.path]]
  if (a) checks.push(['userinfo', a.userinfo], ['host', a.host])
  checks.push(['query', r.query], ['fragment', r.fragment])
  for (const [name, v] of checks) {
    if (v !== undefined && truncated(v)) throw new UriError(`the ${name} has a truncated percent-encoding`)
  }
  let authority
  if (a) {
    authority = ''
    if (a.userinfo !== undefined) authority += pct(a.userinfo) + '@'
    authority += lowerAscii(pct(a.host))
    if (a.port !== undefined) {
      const p = pct(a.port)
      if (p !== '' && p !== DEFAULT_PORT[scheme]) authority += ':' + p
    }
