  let path = removeDots(pct(r.path))
  if (authority !== undefined && path === '') path = '/'
  return {
    scheme, authority, path,
    query: r.query === undefined ? undefined : pct(r.query),
    fragment: r.fragment === undefined ? undefined : pct(r.fragment),
  }
}

export function serialize(r) {
  let s = ''
  if (r.scheme !== undefined) s += r.scheme + ':'
  if (r.authority !== undefined) s += '//' + r.authority
  s += r.path
  if (r.query !== undefined) s += '?' + r.query
  if (r.fragment !== undefined) s += '#' + r.fragment
  return s
}

export function resolve(base, ref) {
  const t = { scheme: undefined, authority: undefined, path: '', query: ref.query, fragment: ref.fragment }
  if (ref.scheme !== undefined) {
    Object.assign(t, { scheme: ref.scheme, authority: ref.authority, path: removeDots(ref.path) })
  } else if (ref.authority !== undefined) {
    Object.assign(t, { scheme: base.scheme, authority: ref.authority, path: removeDots(ref.path) })
